-- Synthetic records and storage metadata only; all writes, including audit, roll back.
begin;set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table prova_itp(actor uuid,azienda uuid,ordine uuid,sub uuid,fase uuid,evidenza uuid,verifica uuid);
insert into prova_itp select sp.user_id,sp.company_id,o.id,gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid() from public.staff_permissions sp join public.orders o on o.company_id=sp.company_id where sp.can_view_sicurezza_cantiere and not sp.sola_lettura and o.deleted_at is null limit 1;
grant select on prova_itp to authenticated;
do $$begin if not exists(select 1 from prova_itp) then raise exception 'Fixture autorizzata non disponibile';end if;end$$;
insert into public.subappaltatori_sicurezza(id,company_id,order_id,ragione_sociale) select sub,azienda,ordine,'TEST ITP ROLLBACK' from prova_itp;
insert into public.order_work_phases(id,company_id,order_id,name,position,start_date,end_date) select fase,azienda,ordine,'TEST ITP FASE',999,'2026-11-01','2026-11-30' from prova_itp;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from prova_itp;set local role authenticated;
insert into public.sicurezza_fascicolo(id,company_id,subappaltatore_id,tipo,titolo,catalogo_id,catalogo_versione) select evidenza,azienda,sub,'visura','TEST ITP VISURA','visura',1 from prova_itp;
reset role;
insert into storage.objects(bucket_id,name) select 'fascicoli-cantiere',azienda::text||'/'||evidenza::text||'/sintetico.pdf' from prova_itp;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from prova_itp;set local role authenticated;
update public.sicurezza_fascicolo e set file_path=f.azienda::text||'/'||f.evidenza::text||'/sintetico.pdf',file_name='sintetico.pdf',stato='verificato' from prova_itp f where e.id=f.evidenza;

reset role;
create temporary table nomi_itp(w1 uuid,w2 uuid,w3 uuid,w4 uuid,ass2 uuid,altra_fase uuid,i1 uuid,i2 uuid,i3 uuid,e1 uuid,e2 uuid,ei1 uuid,ei2 uuid,ei3 uuid);
insert into nomi_itp values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid());
grant select on nomi_itp to authenticated;
insert into public.order_work_phases(id,company_id,order_id,name,position) select n.altra_fase,f.azienda,f.ordine,'TEST NOMI ALTRA FASE',998 from nomi_itp n cross join prova_itp f;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from prova_itp;set local role authenticated;
insert into public.subappaltatori_operai(id,company_id,subappaltatore_id,nome,cognome,mansione) select x.id,f.azienda,f.sub,'TEST NOMINATIVO',x.nome,'Posatore' from nomi_itp n cross join prova_itp f cross join lateral(values(n.w1,'A'),(n.w2,'B'),(n.w3,'ALTRA FASE'))x(id,nome);
insert into public.subappaltatori_assegnazioni(id,company_id,subappaltatore_id,order_id,operaio_id,dal,al,attivita,fase_id) select x.id,f.azienda,f.sub,f.ordine,x.w,'2026-11-01','2026-11-30','TEST NOMI',x.fase from nomi_itp n cross join prova_itp f cross join lateral(values(gen_random_uuid(),n.w1,f.fase),(n.ass2,n.w2,f.fase),(gen_random_uuid(),n.w3,n.altra_fase))x(id,w,fase);
-- The same worker may work in two explicit phases on the same date, while duplicates stay blocked.
insert into public.subappaltatori_assegnazioni(company_id,subappaltatore_id,order_id,operaio_id,dal,al,attivita,fase_id) select f.azienda,f.sub,f.ordine,n.w1,'2026-11-01','2026-11-30','TEST NOMI SECONDA FASE',n.altra_fase from nomi_itp n cross join prova_itp f;
do $$declare f record;n record;begin select * into f from prova_itp;select * into n from nomi_itp;
 begin insert into public.subappaltatori_assegnazioni(company_id,subappaltatore_id,order_id,operaio_id,dal,attivita,fase_id) values(f.azienda,f.sub,f.ordine,n.w1,'2026-11-01','TEST DUPLICATO',f.fase);raise exception 'ASSERT: fase duplicata';exception when unique_violation then null;end;
end$$;
insert into public.sicurezza_incarichi(id,company_id,subappaltatore_id,order_id,ruolo,nominativo,dal,al,stato,nominante,atto_riferimento) select x.id,f.azienda,x.sub,f.ordine,x.ruolo,x.nome,'2026-11-01','2026-11-30','documentato','TEST','TEST senza valore reale' from nomi_itp n cross join prova_itp f cross join lateral(values(n.i1,f.sub,'preposto','TEST PREPOSTO A'),(n.i2,f.sub,'preposto','TEST PREPOSTO B'),(n.i3,null::uuid,'cse','TEST CSE COMMESSA'))x(id,sub,ruolo,nome);
insert into public.sicurezza_fascicolo(id,company_id,subappaltatore_id,order_id,operaio_id,incarico_id,tipo,titolo,catalogo_id,catalogo_versione) select x.id,f.azienda,x.sub,x.ordine,x.w,x.incarico,x.tipo,'TEST NOMI EVIDENZA',x.catalogo,1 from nomi_itp n cross join prova_itp f cross join lateral(values(n.e1,f.sub,null::uuid,n.w1,null::uuid,'formazione','formazione_lavoratori'),(n.e2,f.sub,null::uuid,n.w2,null::uuid,'formazione','formazione_lavoratori'),(n.ei1,f.sub,f.ordine,null::uuid,n.i1,'nomina','nomina_preposto'),(n.ei2,f.sub,f.ordine,null::uuid,n.i2,'nomina','nomina_preposto'),(n.ei3,null::uuid,f.ordine,null::uuid,n.i3,'nomina','nomina_cse'))x(id,sub,ordine,w,incarico,tipo,catalogo);
reset role;
insert into storage.objects(bucket_id,name) select 'fascicoli-cantiere',f.azienda::text||'/'||x.id::text||'/sintetico.pdf' from nomi_itp n cross join prova_itp f cross join lateral(values(n.e1),(n.e2),(n.ei1),(n.ei2),(n.ei3))x(id);
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from prova_itp;set local role authenticated;
update public.sicurezza_fascicolo e set file_path=f.azienda::text||'/'||e.id::text||'/sintetico.pdf',file_name='sintetico.pdf',stato='verificato' from prova_itp f,nomi_itp n where e.id in(n.e1,n.e2,n.ei1,n.ei2,n.ei3);
do $$declare f record;n record;d jsonb;c1 jsonb;c2 jsonb;c4 jsonb;g uuid:=gen_random_uuid();v public.sicurezza_verifiche_itp;v2 uuid:=gen_random_uuid();v3 uuid:=gen_random_uuid();v4 uuid:=gen_random_uuid();attesi jsonb;begin
 select * into f from prova_itp;select * into n from nomi_itp;
 c1:=jsonb_build_object('id',gen_random_uuid(),'titolo','Formazione degli addetti','catalogo_id','formazione_lavoratori','catalogo_versione',1,'applicabilita','applicabile','esito','conforme','riferimento','TEST, solo prova tecnica','note','','evidenze',jsonb_build_array(n.e1),'destinatario','operaio','operaio_id',n.w1,'gruppo_id',g,'copertura','operai_assegnati');
 c2:=c1||jsonb_build_object('id',gen_random_uuid(),'operaio_id',n.w2,'evidenze',jsonb_build_array(n.e2));
 select jsonb_object_agg(id,updated_at) into attesi from public.sicurezza_fascicolo where id in(n.e1,n.e2,n.ei1,n.ei2,n.ei3);
 d:=jsonb_build_object('fase_id',f.fase,'dal','2026-11-01','al','2026-11-30','esito','positivo','attivita','TEST NOMI ROLLBACK','responsabile','Tecnico TEST','ruolo_responsabile','TEST','motivazione','Non è una valutazione reale','completezza',true,'criteri',jsonb_build_array(c1,c2),'contesto_atteso',public.sicurezza_itp_contesto(f.azienda,f.ordine,f.sub,f.fase),'soggetti_attesi',public.sicurezza_itp_soggetti(f.azienda,f.ordine,f.sub),'evidenze_attese',attesi);
 if jsonb_array_length(d->'soggetti_attesi'->'operai')<>3 or jsonb_array_length(d->'soggetti_attesi'->'incarichi')<>3 then raise exception 'ASSERT: fonti nominative non complete o ruolo commessa escluso';end if;
 begin perform public.sicurezza_registra_itp(f.verifica,f.azienda,f.ordine,f.sub,null,d-'soggetti_attesi');raise exception 'ASSERT: token soggetti mancante';exception when serialization_failure then null;end;
 begin perform public.sicurezza_registra_itp(f.verifica,f.azienda,f.ordine,f.sub,null,jsonb_set(d,'{criteri}',jsonb_build_array(c1)));raise exception 'ASSERT: un addetto copre la squadra';exception when raise_exception then if sqlerrm not like 'Manca un addetto assegnato%' then raise;end if;end;
 begin perform public.sicurezza_registra_itp(f.verifica,f.azienda,f.ordine,f.sub,null,jsonb_set(d,'{criteri,1,evidenze}',jsonb_build_array(n.e1)));raise exception 'ASSERT: documento di altro operaio';exception when raise_exception then if sqlerrm not like 'L’evidenza non appartiene al titolare%' then raise;end if;end;
 begin perform public.sicurezza_registra_itp(f.verifica,f.azienda,f.ordine,f.sub,null,jsonb_set(d,'{criteri,1,operaio_id}',to_jsonb(n.w3::text)));raise exception 'ASSERT: addetto di altra fase';exception when raise_exception then if sqlerrm not like 'Operaio cessato o senza assegnazione%' then raise;end if;end;
 v:=public.sicurezza_registra_itp(f.verifica,f.azienda,f.ordine,f.sub,null,d);
 if v.criteri->0->'soggetto_snapshot'->'dati'->>'id'<>n.w1::text or v.criteri->1->'soggetto_snapshot'->'dati'->>'id'<>n.w2::text or jsonb_array_length(v.soggetti->'operai')<>3 then raise exception 'ASSERT: snapshot titolari non corretto';end if;
 update public.subappaltatori_assegnazioni set al='2026-10-31',dal='2026-10-01' where id=n.ass2;
 begin perform public.sicurezza_registra_itp(v2,f.azienda,f.ordine,f.sub,f.verifica,d);raise exception 'ASSERT: periodo cambiato ignorato';exception when serialization_failure then null;end;
 update public.subappaltatori_assegnazioni set dal='2026-11-01',al='2026-11-30' where id=n.ass2;
 insert into public.subappaltatori_operai(id,company_id,subappaltatore_id,nome,cognome,mansione) values(n.w4,f.azienda,f.sub,'TEST NOMINATIVO','NUOVO','Posatore');
 insert into public.subappaltatori_assegnazioni(company_id,subappaltatore_id,order_id,operaio_id,dal,al,attivita,fase_id) values(f.azienda,f.sub,f.ordine,n.w4,'2026-11-01','2026-11-30','TEST NOMI',f.fase);
 begin perform public.sicurezza_registra_itp(v2,f.azienda,f.ordine,f.sub,f.verifica,d);raise exception 'ASSERT: aggiunta di un addetto ignorata';exception when serialization_failure then null;end;
 d:=jsonb_set(d,'{soggetti_attesi}',public.sicurezza_itp_soggetti(f.azienda,f.ordine,f.sub));
 begin perform public.sicurezza_registra_itp(v2,f.azienda,f.ordine,f.sub,f.verifica,d);raise exception 'ASSERT: token aggiornato ma nuovo addetto omesso';exception when raise_exception then if sqlerrm not like 'Manca un addetto assegnato%' then raise;end if;end;
 c4:=c1||jsonb_build_object('id',gen_random_uuid(),'operaio_id',n.w4,'applicabilita','da_chiarire','esito','da_verificare','evidenze','[]'::jsonb);
 d:=jsonb_set(jsonb_set(d,'{criteri}',jsonb_build_array(c1,c2,c4)),'{esito}','"da_integrare"');
 v:=public.sicurezza_registra_itp(v2,f.azienda,f.ordine,f.sub,f.verifica,d);
 if v.esito<>'da_integrare' or jsonb_array_length(v.criteri)<>3 then raise exception 'ASSERT: integrazione senza nuovo addetto';end if;
 -- Both preposti must be represented; their appointment evidence cannot be exchanged.
 c1:=jsonb_build_object('id',gen_random_uuid(),'titolo','Nomine preposti','catalogo_id','nomina_preposto','catalogo_versione',1,'applicabilita','applicabile','esito','conforme','riferimento','TEST','note','','evidenze',jsonb_build_array(n.ei1),'destinatario','incarico','incarico_id',n.i1,'ruolo','preposto','gruppo_id',gen_random_uuid(),'copertura','incarichi_ruolo');
 c2:=c1||jsonb_build_object('id',gen_random_uuid(),'incarico_id',n.i2,'evidenze',jsonb_build_array(n.ei2));
 d:=jsonb_set(jsonb_set(d,'{criteri}',jsonb_build_array(c1,c2)),'{esito}','"positivo"');
 begin perform public.sicurezza_registra_itp(v3,f.azienda,f.ordine,f.sub,v2,jsonb_set(d,'{criteri}',jsonb_build_array(c1)));raise exception 'ASSERT: incarico omesso dal ruolo';exception when raise_exception then if sqlerrm not like 'Manca un incarico pertinente%' then raise;end if;end;
 begin perform public.sicurezza_registra_itp(v3,f.azienda,f.ordine,f.sub,v2,jsonb_set(d,'{criteri,1,evidenze}',jsonb_build_array(n.ei1)));raise exception 'ASSERT: nomina di altro preposto';exception when raise_exception then if sqlerrm not like 'L’evidenza non appartiene al titolare%' then raise;end if;end;
 update public.sicurezza_incarichi set stato='proposto' where id=n.i2;
 begin perform public.sicurezza_registra_itp(v3,f.azienda,f.ordine,f.sub,v2,d);raise exception 'ASSERT: incarico cambiato ignorato';exception when serialization_failure then null;end;
 d:=jsonb_set(d,'{soggetti_attesi}',public.sicurezza_itp_soggetti(f.azienda,f.ordine,f.sub));
 begin perform public.sicurezza_registra_itp(v3,f.azienda,f.ordine,f.sub,v2,d);raise exception 'ASSERT: incarico non documentato per positivo';exception when raise_exception then if sqlerrm not like 'Incarico non documentato%' then raise;end if;end;
 update public.sicurezza_incarichi set stato='documentato' where id=n.i2;
 d:=jsonb_set(d,'{soggetti_attesi}',public.sicurezza_itp_soggetti(f.azienda,f.ordine,f.sub));
 v:=public.sicurezza_registra_itp(v3,f.azienda,f.ordine,f.sub,v2,d);
 -- A common appointment of this case is a valid source without attributing it to the subcontractor.
 c1:=jsonb_build_object('id',gen_random_uuid(),'titolo','Nomina CSE','catalogo_id','nomina_cse','catalogo_versione',1,'applicabilita','applicabile','esito','conforme','riferimento','TEST','note','','evidenze',jsonb_build_array(n.ei3),'destinatario','incarico','incarico_id',n.i3,'ruolo','cse');
 d:=jsonb_set(d,'{criteri}',jsonb_build_array(c1));
 v:=public.sicurezza_registra_itp(v4,f.azienda,f.ordine,f.sub,v3,d);
 if v.criteri->0->'soggetto_snapshot'->'dati'->>'nominativo'<>'TEST CSE COMMESSA' then raise exception 'ASSERT: titolare del cantiere inventato';end if;
end$$;
reset role;
do $$declare f record;n record;begin select * into f from prova_itp;select * into n from nomi_itp;
 begin delete from public.order_work_phases where id=f.fase;raise exception 'ASSERT: fase con addetti eliminata';exception when raise_exception then if sqlerrm not like 'La fase ha assegnazioni di addetti%' then raise;end if;end;
 begin update public.subappaltatori_assegnazioni set fase_id=(select id from public.order_work_phases where order_id<>f.ordine limit 1) where id=n.ass2;raise exception 'ASSERT: fase estranea assegnata';exception when raise_exception then if sqlerrm not like 'La fase non appartiene alla commessa%' then raise;end if;end;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);set local role authenticated;
do $$declare f record;begin select * into f from prova_itp;
 begin perform public.sicurezza_itp_soggetti(f.azienda,f.ordine,f.sub);raise exception 'ASSERT: organico esposto a utente estraneo';exception when insufficient_privilege then null;end;
end$$;reset role;
select 'PASS: titolari nominativi, evidenze proprie, copertura addetti/ruoli, fasi, cambiamento roster e integrazione CSE della commessa' as esito;
rollback;
